import java.util.*;

public class Main {
    public static void main(String[] args) {
        FeedService feedService = new FeedService(1000); // celebrity threshold: 1000 followers

        Author authorA = new Author("author-A", 5, Arrays.asList("user-U", "user-2", "user-3", "user-4", "user-5"));
        Author authorB = new Author("author-B", 2000000, Collections.emptyList()); // celebrity, no push list needed

        // Scores are precomputed here for clarity, representing recency, engagement, and affinity for viewer U.
        Post postFromA = new Post("P1", "author-A", scoreFor(90, 10, 80)); // ordinary post, high affinity with U
        Post postFromB = new Post("P2", "author-B", scoreFor(95, 90, 10)); // celebrity post, high engagement, low affinity with U

        feedService.publish(authorA, postFromA); // fan-out-on-write: pushed to all 5 followers, including U
        feedService.publish(authorB, postFromB); // fan-out-on-read: NOT pushed anywhere, just stored

        List<String> cachedIds = new ArrayList<>();
        for (Post post : feedService.precomputedCacheFor("user-U")) cachedIds.add(post.postId);
        System.out.println("U's precomputed cache after A's post: " + cachedIds);
        System.out.println("U's precomputed cache does NOT contain celebrity B's post: " + !feedService.precomputedCacheFor("user-U").contains(postFromB));

        List<Post> feed = feedService.getFeed("user-U", Collections.singletonList("author-B"));
        System.out.println("U's final ranked feed:");
        for (Post post : feed) {
            System.out.println("  " + post.postId + " (score " + post.score + ")");
        }
    }

    // recency, engagement, and affinity are each on a 0-100 scale; weights reflect
    // that engagement matters twice as much as recency, and affinity slightly more.
    static double scoreFor(double recency, double engagement, double affinity) {
        return recency * 1.0 + engagement * 2.0 + affinity * 1.5;
    }
}

