// Implements hybrid fan-out: pushes an ordinary account's post directly into
// every follower's precomputed cache, but stores a celebrity account's post
// for pull-based reading instead, then merges and ranks both at read time.
class FeedService {
    private final int celebrityThreshold;
    private final Map<String, List<Post>> precomputedFeed = new HashMap<>(); // followerId -> pushed posts
    private final Map<String, List<Post>> celebrityPosts = new HashMap<>();     // authorId -> that celebrity's own posts

    FeedService(int celebrityThreshold) {
        this.celebrityThreshold = celebrityThreshold;
    }

    void publish(Author author, Post post) {
        if (author.followerCount <= celebrityThreshold) {
            // Fan-out-on-write: push this post into every follower's own precomputed cache now.
            for (String followerId : author.followerIds) {
                precomputedFeed.computeIfAbsent(followerId, id -> new ArrayList<>()).add(post);
            }
        } else {
            // Fan-out-on-read: never pushed; stored once for any follower to pull later.
            celebrityPosts.computeIfAbsent(author.authorId, id -> new ArrayList<>()).add(post);
        }
    }

    List<Post> precomputedCacheFor(String userId) {
        return precomputedFeed.getOrDefault(userId, Collections.emptyList());
    }

    // Merges a user's precomputed cache with posts pulled live from any
    // followed celebrity accounts, then ranks the combined result by score.
    List<Post> getFeed(String userId, List<String> followedCelebrityAuthorIds) {
        List<Post> feed = new ArrayList<>(precomputedCacheFor(userId));
        for (String celebrityId : followedCelebrityAuthorIds) {
            feed.addAll(celebrityPosts.getOrDefault(celebrityId, Collections.emptyList())); // pull at read time
        }
        feed.sort((a, b) -> Double.compare(b.score, a.score)); // rank by score, highest first
        return feed;
    }
}

