class Author:
    # An author account: its id, follower count (which decides its fan-out
    # strategy), and the explicit list of its followers (only needed for
    # ordinary, fan-out-on-write accounts).
    def __init__(self, author_id, follower_count, follower_ids):
        self.author_id = author_id
        self.follower_count = follower_count
        self.follower_ids = follower_ids


class FeedService:
    # Implements hybrid fan-out: pushes an ordinary account's post directly into
    # every follower's precomputed cache, but stores a celebrity account's post
    # for pull-based reading instead, then merges and ranks both at read time.
    def __init__(self, celebrity_threshold):
        self.celebrity_threshold = celebrity_threshold
        self.precomputed_feed = {}  # followerId -> list of pushed posts
        self.celebrity_posts = {}   # authorId -> that celebrity's own posts

    def publish(self, author, post):
        if author.follower_count <= self.celebrity_threshold:
            # Fan-out-on-write: push this post into every follower's own precomputed cache now.
            for follower_id in author.follower_ids:
                self.precomputed_feed.setdefault(follower_id, []).append(post)
        else:
            # Fan-out-on-read: never pushed; stored once for any follower to pull later.
            self.celebrity_posts.setdefault(author.author_id, []).append(post)

    def precomputed_cache_for(self, user_id):
        return self.precomputed_feed.get(user_id, [])

    def get_feed(self, user_id, followed_celebrity_author_ids):
        feed = list(self.precomputed_cache_for(user_id))
        for celebrity_id in followed_celebrity_author_ids:
            feed.extend(self.celebrity_posts.get(celebrity_id, []))  # pull at read time
        feed.sort(key=lambda post: post.score, reverse=True)  # rank by score, highest first
        return feed


def score_for(recency, engagement, affinity):
    # recency, engagement, and affinity are each on a 0-100 scale; weights reflect
    # that engagement matters twice as much as recency, and affinity slightly more.
    return recency * 1.0 + engagement * 2.0 + affinity * 1.5


def main():
    feed_service = FeedService(1000)  # celebrity threshold: 1000 followers

    author_a = Author("author-A", 5, ["user-U", "user-2", "user-3", "user-4", "user-5"])
    author_b = Author("author-B", 2000000, [])  # celebrity, no push list needed

    # Scores are precomputed here for clarity, representing recency, engagement, and affinity for viewer U.
    post_from_a = Post("P1", "author-A", score_for(90, 10, 80))  # ordinary post, high affinity with U
    post_from_b = Post("P2", "author-B", score_for(95, 90, 10))  # celebrity post, high engagement, low affinity with U

    feed_service.publish(author_a, post_from_a)  # fan-out-on-write: pushed to all 5 followers, including U
    feed_service.publish(author_b, post_from_b)  # fan-out-on-read: NOT pushed anywhere, just stored

    cache_ids = [post.post_id for post in feed_service.precomputed_cache_for("user-U")]
    print("U's precomputed cache after A's post:", cache_ids)
    print("U's precomputed cache does NOT contain celebrity B's post:", post_from_b not in feed_service.precomputed_cache_for("user-U"))

    feed = feed_service.get_feed("user-U", ["author-B"])
    print("U's final ranked feed:")
    for post in feed:
        print(f"  {post.post_id} (score {post.score})")


if __name__ == "__main__":
    main()

