#include <iostream>
#include <map>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

// One published post, with a precomputed ranking score for this demo's viewer.
struct Post {
    string postId;
    string authorId;
    double score;
};

// An author account: its id, follower count (which decides its fan-out
// strategy), and the explicit list of its followers (only needed for
// ordinary, fan-out-on-write accounts).
struct Author {
    string authorId;
    int followerCount;
    vector<string> followerIds;
};

// Implements hybrid fan-out: pushes an ordinary account's post directly into
// every follower's precomputed cache, but stores a celebrity account's post
// for pull-based reading instead, then merges and ranks both at read time.
class FeedService {
public:
    FeedService(int celebrityThreshold) : celebrityThreshold(celebrityThreshold) {}

    void publish(const Author& author, const Post& post) {
        if (author.followerCount <= celebrityThreshold) {
            // Fan-out-on-write: push this post into every follower's own precomputed cache now.
            for (const string& followerId : author.followerIds) {
                precomputedFeed[followerId].push_back(post);
            }
        } else {
            // Fan-out-on-read: never pushed; stored once for any follower to pull later.
            celebrityPosts[author.authorId].push_back(post);
        }
    }

    vector<Post> precomputedCacheFor(const string& userId) {
        auto it = precomputedFeed.find(userId);
        return (it != precomputedFeed.end()) ? it->second : vector<Post>();
    }

    vector<Post> getFeed(const string& userId, const vector<string>& followedCelebrityAuthorIds) {
        vector<Post> feed = precomputedCacheFor(userId);
        for (const string& celebrityId : followedCelebrityAuthorIds) {
            auto it = celebrityPosts.find(celebrityId);
            if (it != celebrityPosts.end()) {
                feed.insert(feed.end(), it->second.begin(), it->second.end()); // pull at read time
            }
        }
        sort(feed.begin(), feed.end(), [](const Post& a, const Post& b) { return a.score > b.score; }); // highest first
        return feed;
    }

private:
    int celebrityThreshold;
    map<string, vector<Post>> precomputedFeed; // followerId -> pushed posts
    map<string, vector<Post>> celebrityPosts;    // authorId -> that celebrity's own posts
};

// recency, engagement, and affinity are each on a 0-100 scale; weights reflect
// that engagement matters twice as much as recency, and affinity slightly more.
double scoreFor(double recency, double engagement, double affinity) {
    return recency * 1.0 + engagement * 2.0 + affinity * 1.5;
}

int main() {
    FeedService feedService(1000); // celebrity threshold: 1000 followers

    Author authorA{"author-A", 5, {"user-U", "user-2", "user-3", "user-4", "user-5"}};
    Author authorB{"author-B", 2000000, {}}; // celebrity, no push list needed

    // Scores are precomputed here for clarity, representing recency, engagement, and affinity for viewer U.
    Post postFromA{"P1", "author-A", scoreFor(90, 10, 80)}; // ordinary post, high affinity with U
    Post postFromB{"P2", "author-B", scoreFor(95, 90, 10)}; // celebrity post, high engagement, low affinity with U

    feedService.publish(authorA, postFromA); // fan-out-on-write: pushed to all 5 followers, including U
    feedService.publish(authorB, postFromB); // fan-out-on-read: NOT pushed anywhere, just stored

    vector<Post> cache = feedService.precomputedCacheFor("user-U");
    cout << "U's precomputed cache after A's post: ";
    for (const auto& post : cache) cout << post.postId << " ";
    cout << endl;

    bool hasB = false;
    for (const auto& post : cache) if (post.postId == postFromB.postId) hasB = true;
    cout << "U's precomputed cache does NOT contain celebrity B's post: " << (!hasB ? "true" : "false") << endl;

    vector<Post> feed = feedService.getFeed("user-U", {"author-B"});
    cout << "U's final ranked feed:" << endl;
    for (const auto& post : feed) {
        cout << "  " << post.postId << " (score " << post.score << ")" << endl;
    }

    return 0;
}

